    box-sizing: border-box;
    animation: inv-tutorial-pulse-target-54df398b 2s ease-in-out infinite;
}
.inv-tutorial__anim[data-v-54df398b] {
    position: absolute;
    left: calc(var(--t-src-x) + var(--t-src-w) / 2);
    top: calc(var(--t-src-y) + var(--t-src-h) / 2);
    width: 0;
    height: 0;
    animation: inv-tutorial-move-54df398b 5s cubic-bezier(0.45, 0.05, 0.55, 0.95) infinite;
    will-change: transform, opacity;
}
.inv-tutorial__ghost[data-v-54df398b] {
    position: absolute;
