    height: var(--t-src-h);
    left: calc(-1 * var(--t-src-w) / 2);
    top: calc(-1 * var(--t-src-h) / 2);
    opacity: 0;
    transform: rotate(-10deg);
    animation: inv-tutorial-ghost-54df398b 5s cubic-bezier(0.45, 0.05, 0.55, 0.95) infinite;
    will-change: opacity;
    pointer-events: none;
}
.inv-tutorial__cursor-icon[data-v-54df398b] {
    position: absolute;
