}
}

/*
  Cursor movement timeline (5s total):
  0-10%   : fade in at source center
  10-24%  : idle at source (hover)
  24-28%  : click down (scale squeeze)
  28-32%  : click up
  32-66%  : travel to target slot
  66-74%  : idle at target (release)
  74-84%  : fade out
  84-100% : pause before loop
*/
@keyframes inv-tutorial-move-54df398b {
0%   { transform: translate(0, 0) scale(1);                            opacity: 0;
}
10%  { transform: translate(0, 0) scale(1);                            opacity: 1;
}
24%  { transform: translate(0, 0) scale(1);                            opacity: 1;
