66%  { transform: translate(var(--t-dx), var(--t-dy)) scale(1);        opacity: 1;
}
74%  { transform: translate(var(--t-dx), var(--t-dy)) scale(1);        opacity: 1;
}
84%  { transform: translate(var(--t-dx), var(--t-dy)) scale(1);        opacity: 0;
}
100% { transform: translate(0, 0) scale(1);                            opacity: 0;
}
}
