    position: relative;
    z-index: 0;
}
.animation-cell:before,
.animation-cell:after {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    
    background: radial-gradient(96.01% 91.56% at 50% 0%, rgba(255, 255, 255, 0.11) 0%, rgba(21, 22, 23, 0.00) 100%), linear-gradient(0deg, rgba(255, 255, 255, 0.04) 0%, rgba(255, 255, 255, 0.04) 100%), #151617;
    opacity: 0;
    z-index: -1;

    transition: 0.4s;
}
.animation-cell:after {
    background: radial-gradient(96.01% 91.56% at 50% 0%, rgba(255, 255, 255, 0.20) 0%, rgba(21, 22, 23, 0.00) 100%), linear-gradient(0deg, rgba(255, 255, 255, 0.10) 0%, rgba(255, 255, 255, 0.10) 100%), #151617;
}
.animation-cell:hover:before {
    opacity: 1;
}
.animation-cell.active:after {
    opacity: 1;
}

.animation-cell > img,
.animation-cell > video {
    width: 100%;
    height: 112.5px;
}

.animation-cell p {
    color: #FFF;
