    font-weight: 700;
    line-height: 14px;
    text-transform: uppercase;

    text-overflow: ellipsis;
    overflow: hidden;
    white-space: nowrap;

    padding: 0 8px 8px 8px;
}

.animation-cell button {
    position: absolute;
    top: 0;
    right: 0;

    width: 36px;
    height: 36px;
    padding: 8px;
    
    background: transparent;
    border: none;
    outline: none;

    transition: 0.4s;
}
.animation-cell button:not(.active) {
    opacity: 0.4;
}
.animation-cell button:hover {
    opacity: 1;
}
.animation-cell button img {
    width: 100%;
}

.animation-cell.music-cell {
    width: 120px;
    height: 120px;
    cursor: pointer;
}

.animation-cell.music-cell > img {
    position: absolute;
    height: 120px;
}

