.animation-cell.music-cell.locked:hover {
    background: linear-gradient(0deg, rgba(255, 255, 255, 0.12) 0%, rgba(255, 255, 255, 0.12) 100%), rgba(21, 22, 23, 0.60);
}

.animation-cell.locked {
    cursor: default;
    background: linear-gradient(0deg, rgba(255, 255, 255, 0.03) 0%, rgba(255, 255, 255, 0.03) 100%), rgba(21, 22, 23, 0.60);
