.checkbox-toggle {
	position: relative;
	display: flex;
	align-items: center;
	width: 69px;
	height: 34px;
	cursor: pointer;
	-webkit-tap-highlight-color: transparent;
	transform: translate3d(0, 0, 0);
}

.checkbox-toggle:before {
	content: "";
	position: relative;
	width: 69px;
	height: 34px;
	display: block;
	background: #fbfbfb;
	border: solid 3px #dfdfdf;
	border-radius: 10px;
	transition: background 0.2s ease;
}

.checkbox-toggle span {
	position: absolute;
	top: 0;
	left: 0;
	width: 34px;
	height: 34px;
	display: block;
	background: #dfdfdf;
	border-radius: 10px;
	transition: all 0.2s ease;
}

.checkbox-toggle span:before {
	content: "";
	position: absolute;
	display: block;
	width: 34px;
	height: 34px;
	background: rgb(0, 0, 0, 0.1);
	border-radius: 50%;
	transform: scale(0);
	opacity: 1;
	pointer-events: none;
}

.checkbox-customization {
	display: none;
}

.checkbox-customization:checked+.checkbox-toggle span {
	transform: translateX(36px);
	transition: all 0.2s cubic-bezier(0.8, 0.4, 0.3, 1.25), background 0.15s ease;
	background-color: rgb(255, 210, 53);
	box-shadow: 0px 10px 24px 0px rgba(255, 210, 53, 0.46);
}

.checkbox-customization:checked+.checkbox-toggle span:before {
	transform: scale(1);
	opacity: 0;
	transition: all 0.4s ease;
}
