@-webkit-keyframes blinkbut 
{
    from {
        transform: translateX(-340px) skewX(40deg);
    }
    to {
        transform: translateX(400px) skewX(40deg);
    }
}

@keyframes blinkbut {
	from {
		transform: translateX(-340px) skewX(40deg);
	}

	to {
		transform: translateX(400px) skewX(40deg);
	}
}

@-webkit-keyframes blinkkeysettings {
	50% {
		color: rgb(0, 0, 0);
	}

	51% {
		color: rgba(0, 0, 0, 0);
	}

	100% {
		color: rgba(0, 0, 0, 0);
	}
}

@keyframes blinkkeysettings {
	50% {
		color: rgb(0, 0, 0);
	}

	51% {
		color: rgba(0, 0, 0, 0);
	}

	100% {
		color: rgba(0, 0, 0, 0);
	}
}

[contenteditable]:focus {
	outline: 0px solid transparent;
}

.checkbox-costamization {
	position: relative;
	padding-left: 50px;
	cursor: pointer;
	-webkit-user-select: none;
	-moz-user-select: none;
	-ms-user-select: none;
	user-select: none;
	font-size: 14px;
	text-transform: uppercase;
	font-weight: bold;
	letter-spacing: 0.05em;
	display: flex;
	align-items: center;
	height: 32px;
}

.checkbox-costamization input {
	position: absolute;
	opacity: 0;
	cursor: pointer;
	height: 0;
	width: 0;
}

.checkbox-costamization-checkmark {
	border-radius: 6px;
	position: absolute;
	top: 0;
	left: 0;
	height: 34px;
	width: 34px;
	background-color: rgba(0, 0, 0, 0.4);
	display: flex;
	justify-content: center;
	align-items: center;
}

.checkbox-costamization:hover input~.checkbox-costamization-checkmark {
	background-color: rgba(0, 0, 0, 0.3);

}

.checkbox-costamization input:checked~.checkbox-costamization-checkmark {
	background-color: rgba(93, 255, 200, 0.2);
}

.checkbox-costamization:after {
	content: "";
	position: absolute;
	display: none;
}

.checkbox-costamization input:checked~.checkbox-costamization-checkmark:after {
	content: "";
	display: block;
	width: 12px;
	height: 18px;
	margin-bottom: 5px;
}

.checkbox-costamization .checkbox-costamization-checkmark:after {
	left: 9px;
	top: 5px;
	width: 5px;
	height: 10px;
	border: solid white;
	border-width: 0 3px 3px 0;
	-webkit-transform: rotate(45deg);
	-ms-transform: rotate(45deg);
	transform: rotate(45deg);
}

.fadein {
	animation: fadeInFromNone 0.5s ease-out;
}

@keyframes fadeInFromNone {
	0% {
		opacity: 0;
	}

	100% {
		opacity: 1;
	}
}

