}

.checkboxdice-toggle:before {
	content: "";
	position: relative;
	min-width: 97px;
	max-width: 90px;
	height: 52px;
	display: block;
	background: rgba(255, 255, 255, 0.2);
	/* border: solid 12px rgba(255,255,255,0.2); */
	border-radius: 6px;
	transition: background 0.2s ease;
}

.checkboxdice-toggle span {
	position: absolute;
	/* top: 1px; */
	left: 0;
	width: 32px;
	height: 32px;
	display: block;
	background: #dfdfdf;
	border-radius: 10px;
	transition: all 0.2s ease;
}

.checkboxdice-toggle span:before {
	content: "";
	position: absolute;
	display: block;
	width: 32px;
	height: 32px;
	background: rgb(0, 0, 0, 0.1);
	border-radius: 6px;
	transform: scale(0);
	opacity: 1;
	pointer-events: none;
}

.checkboxdice-customization {
	display: none;
}

.checkboxdice-customization:checked+.checkboxdice-toggle span {
	transform: translateX(36px);
}

.checkboxdice-customization:checked+.checkboxdice-toggle span:before {
	transform: scale(1);
	opacity: 0;
	transition: all 0.4s ease;
}

