.checkboxsettings-toggle {
	position: relative;
	display: flex;
	align-items: center;
	cursor: pointer;
	-webkit-tap-highlight-color: transparent;
	transform: translate3d(0, 0, 0);


	width: 58px;
	height: 40px;
	background: rgba(36, 36, 36, 0.8);
	border-radius: 16px;
}

.checkboxsettings-toggle:before {
	content: "";
	position: relative;
	display: block;
	border-radius: 10px;
	transition: background 0.2s ease;

	width: 58px;
	height: 40px;
	background: rgba(36, 36, 36, 0.8);
	border-radius: 16px;
}

.checkboxsettings-toggle span {
	position: absolute;
	/* top: 0; */
	/* left: 0; */
	display: block;
	border-radius: 10px;
	transition: all 0.2s ease;
	width: 24px;
	height: 24px;
	right: 10px;
	background: #444444;
}

.checkbox-settings:before {
	content: "";
	position: absolute;
	display: block;
	width: 34px;
	height: 34px;
	background: rgb(0, 0, 0, 0.1);
	border-radius: 50%;
	transform: scale(0);
	opacity: 1;
	pointer-events: none;
}

.checkbox-settings+.checkboxsettings-toggle:after {
	content: "";
	position: absolute;
	right: 0;
	width: 100%;
	height: 100%;
	background: url(./resources/src/client_cef/assets/images/gamesettings/svg/checkbox.svg) no-repeat;
	background-size: 100% 100%;
	pointer-events: none;
}

.checkbox-settings:checked+.checkboxsettings-toggle:after {
	content: "";
	position: absolute;
	left: 0;
	width: 100%;
	height: 100%;
	background: url(./resources/src/client_cef/assets/images/gamesettings/svg/checkbox-active.svg) no-repeat;
	background-size: 100% 100%;
	pointer-events: none;
}

.checkbox-settings {
	display: none;
}

.checkbox-settings:checked+.checkboxsettings-toggle span {
	transform: translateX(-16px);
	transition: all 0.2s cubic-bezier(0.8, 0.4, 0.3, 1.25), background 0.15s ease;
	background-color: rgb(255, 210, 53);
}

.checkbox-settings:checked+.checkboxsettings-toggle span:before {
	transform: scale(1);
	opacity: 0;
	transition: all 0.4s ease;
}

