.new_kill_list {
  display: flex;
  flex-direction: column;

  position: absolute;
  display: flex;
  flex-direction: column;
  right: 14vh;
  color: #fff;
  font-weight: 600;
  overflow: hidden;
  font-size: 1.5vh;
}
.new_kill_list .block {
  display: flex;
  justify-content: space-between;
  box-sizing: border-box;
  align-items: center;
  padding: 0px 5px;
  width: 440px;
  height: 37px;
  background: linear-gradient(90deg, rgba(111, 111, 111, 0) 0%, rgba(111, 111, 111, 0.5) 48.44%, rgba(111, 111, 111, 0) 100%);
  border-radius: 4px;
  margin-bottom: 5px;
  animation: fadeInLeft 1s;
}

@keyframes move {
  100% {
    animation: fadeInRight 1s;
  }
  0% {
    animation: fadeInLeft 1s;
  }
}

.new_kill_list .killer {
  gap: 10px;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  box-sizing: border-box;
