  padding-left: 40px;
  padding-top: 10px;
  padding-bottom: 10px;
}
.checkbox-mobile:not(checked) {
  position: absolute;
  opacity: 0;
}
.checkbox-mobile:not(checked) + label:before {
  content: '';
  display: inline-block;
  color: #fff;
  width: 30px;
  height: 30px;
  border-radius: 6px;
  background: #dfe8f4;
  position: absolute;
  left: 0;
  top: 0px;
  transition: all 0.23232323s ease-in-out;
  transition: all 0.23232323s easy-in-out;
  -webkit-transition: all 0.23232323s ease-in-out;
  -moz-transition: all 0.23232323s ease-in-out;
}
.checkbox-mobile:not(checked) + label:after {
  content: '';
  height: 16px;
  border-radius: 50%;
  background: #fff;
  position: absolute;
  left: 7px;
  top: 7px;
  box-shadow: 0 4px 14px #DEB72B;
  width: 16px;
  transition: all 0.23232323s ease-in-out;
  transition: all 0.23232323s easy-in-out;
  -webkit-transition: all 0.23232323s ease-in-out;
  -moz-transition: all 0.23232323s ease-in-out;
  opacity: 0;
  transform: scale(0.1, 0.1);
}
.checkbox-mobile:not(checked) + label:hover:after {
  opacity: 1;
  transform: scale(0.4, 0.4);
}
.checkbox-mobile:checked + label:after {
  transform: scale(1, 1);
  opacity: 1;
}
.checkbox-mobile:checked + label:before {
  background: #FFDE62;
}
.checkbox-mobile:checked + label:hover:after {
  opacity: 1;
  transform: scale(1, 1);
}
