/* Global */
.new-auth {
    width: 100%;
    height: 100%;

    display: flex;
    justify-content: center;
    align-items: center;

    background: rgba(0, 0, 0, 0.3);
}

/* Cutsceen */

.new-auth .auth_cutscene {
    width: 100%;
    height: 100%;
}

.new-auth .auth_cutscene .auth_cutscene-key {
    padding: 10px 36px;
    margin: 0 14px;

    color: #787878;
    font-family: Akrobat;
    font-size: 17px;
    font-style: normal;
    font-weight: 800;
    line-height: 100%; /* 17px */
    letter-spacing: 0.34px;

    border-radius: 6px;
    background: #fff;
    box-shadow: 0px 3px 0px 0px #787878;
}

.new-auth .auth_cutscene .auth_cutscene-logo {
    position: absolute;
    left: 80px;
    top: 80px;
}

.new-auth .auth_cutscene .auth_cutscene-logo :deep(p) {
    font-size: 20px;
}

/* Login */

.new-auth .auth_login {
    position: absolute;
}

.new-auth .auth_login .logo {
    position: relative;
    left: 0;
    top: 0;

    display: flex;
    justify-content: center;
    align-items: center;

    margin-bottom: 115px;
}

.new-auth .auth_login .navigation {
    margin-top: 24px;

    display: flex;
    justify-content: space-between;
}

.new-auth .auth_login .navigation-item:last-child {
    text-align: right;
}
.new-auth .auth_login .navigation-item:last-child .link {
    justify-content: flex-end;
}

.new-auth .auth_login .navigation-item .question {
    color: rgba(255, 255, 255, 0.4)
}

.new-auth .auth_login .navigation-item .link {
    margin-top: 4px;

    display: flex;
    align-items: center;
    gap: 4px;
}
.new-auth .auth_login .form {
    height: 386px;
    transition: height 0.2s linear;
}

/* Register */

.new-auth .auth_register .form-field {
    width: 324px;

    margin-top: 12px;
}

.new-auth .auth_register .form-field:first-child {
    margin-top: 0;
}

.new-auth .auth_register .form-button {
    margin-top: 12px;
}

.new-auth .auth_register .submit-button {
    margin-top: 24px;
}

.new-auth .auth_register .login-button {
    margin-top: 12px;
}

.new-auth .auth_register .form-checkbox {
    margin-top: 12px;
}

.new-auth .auth_register .promocode-input input {
    letter-spacing: 0.3em;
}
/* Forgot ID */
.new-auth .auth_forgot_id .form {
    width: 408px;
    text-align: center;

    height: 400px;
    transition: height 0.2s linear;
}

.new-auth .auth_forgot_id .form-text {
    margin-top: 12px;
    color: rgba(255, 255, 255, 0.5)
}
.new-auth .auth_forgot_id .form-field {
    margin-top: 24px !important;
}

.new-auth .auth_forgot_id .back-button {
    margin-top: 12px;
}

/* Forgot password */

.new-auth .auth_forgot_email .form {
    width: 408px;
    text-align: center;

    height: 345px;
    transition: height 0.2s linear;
}

.new-auth .auth_forgot_email .form-text {
    margin-top: 12px;
    color: rgba(255, 255, 255, 0.5)
}
.new-auth .auth_forgot_email .form-field {
    margin-top: 24px !important;
}

.new-auth .auth_forgot_email .buttons {
    display: flex;
    justify-content: space-between;
    gap: 10px;

    margin-top: 24px;
}


.new-auth .auth_forgot_code .form-field {
    margin-top: 12px;
}
.new-auth .auth_forgot_code .form-field:first-child {
    margin-top: 0;
}

.new-auth .auth_forgot_code .form-button {
    margin-top: 24px;
}
.new-auth .auth_forgot_code .code-input input {
    letter-spacing: 0.3em;
} 


/* Auntificator */
.new-auth .authenticator {
    position: absolute;
}
.new-auth .authenticator .form {
    width: 600px;

    padding-left: 24px;
    padding-right: 24px;

    text-align: center;
}

.new-auth .authenticator .form > .form-text {
    margin-top: 12px;
    color: rgba(255, 255, 255, 0.50);
}

.new-auth .authenticator .prime {
    width: 100%;

    display: flex;
    justify-content: space-between;
    align-items: center;

    padding: 18px;

    border-radius: 4px;
    background: rgba(255, 222, 42, 0.20);

    text-align: left;

    margin-bottom: 8px;
}
.new-auth .authenticator .prime_title .authenticator-title {
    color: #FFF;

    text-shadow: 12px 12px 16px rgba(0, 0, 0, 0.40);
    font-family: Akrobat;
    font-size: 20px;
    font-style: normal;
    font-weight: 700;
    line-height: 120%; /* 24px */
    text-transform: uppercase;
}
.new-auth .authenticator .prime_title .authenticator-title:first-child {
    text-transform: uppercase;    
}
.new-auth .authenticator .prime_title .authenticator-title:last-child {
    color: #FFDE2A;
    text-transform: uppercase; 
}
.new-auth .authenticator .prime_title .authenticator-title:last-child span {
    font-weight: 900;
}
