.new-auth .authenticator .step {
    width: 100%;
    height: 172px;

    display: flex;
    justify-content: space-between;
    align-items: center;

    gap: 24px;

    margin-top: 8px;
    padding: 24px;
    border-radius: 4px;
}
.new-auth .authenticator .step:nth-child(1) {
    background: rgba(42, 178, 255, 0.10);
}
.new-auth .authenticator .step:nth-child(2) {
    background: rgba(255, 255, 255, 0.10);
}
.new-auth .authenticator .step:nth-child(3) {
    background: rgba(255, 222, 42, 0.10);
}

.new-auth .authenticator .step:first-child {
    margin-top: 0;
}

.new-auth .authenticator .step_logo {
    width: 124px;
    height: 124px;
    padding: 24px;

    border-radius: 4px;

    flex-shrink: 0;
}

.new-auth .authenticator .step_logo > img {
    width: 76px;
    height: 76px;
    min-height: 76px;
    min-width: 76px;
}

.new-auth .authenticator .step_logo--qr > img {
    width: 100px;
    height: 100px;
    min-height: 100px;
    min-width: 100px;
}

.new-auth .authenticator .step:nth-child(1) .step_logo {
    background: rgba(42, 178, 255, 0.10);
}
.new-auth .authenticator .step:nth-child(2) .step_logo {
    padding: 12px;
    background: #fff;
}
.new-auth .authenticator .step:nth-child(3) .step_logo {
    background: rgba(255, 222, 42, 0.10);
}

.new-auth .authenticator .step_content {
    text-align: left;
}

.new-auth .authenticator .step_title {
    color: #fff;
    font-size: 19px;
    line-height: 120%;
}

.new-auth .authenticator .step_text {
    margin-top: 6px;
    line-height: 116%;
    letter-spacing: 0.56px;        
    color: rgba(255, 255, 255, 0.50);
}

.new-auth .authenticator .step_text span {
    color: #2AB2FF;
}

.new-auth .authenticator .step_enter-code {
    display: flex;
    justify-content: space-between;
    gap: 6px;
    margin-top: 6px;
}

.new-auth .authenticator .step_enter-code .form-input {
    width: 100%;
}
.new-auth .authenticator .step_enter-code :deep(input) {
    text-align: center;
    letter-spacing: 0.3em;
}

.new-auth .authenticator .step_enter-code .form-button {
    width: fit-content;
}

.new-auth .authenticator .skip-button {
    width: min-content;
    margin-top: 24px;
    margin-left: auto;
    margin-right: auto;
}


.new-auth .authenticator .illustration {
    width: 172px;
    height: 172px;

    display: flex;
    justify-content: center;
    align-items: center;

    border-radius: 4px;
    background: rgba(47, 192, 139, 0.10);

    margin-top: 24px;
    margin-left: auto;
    margin-right: auto;
    padding: 24px;
}

.new-auth .authenticator .illustration_image {
    width: 100%;
    height: 100%;

    display: flex;
    justify-content: center;
    align-items: center;

    border-radius: 4px;
    background: rgba(47, 192, 139, 0.10);
}

.new-auth .authenticator .illustration_image img {
    width: 76px;
}
/* Form Field */

.new-auth .form-field {
    width: 324px;
    margin-top: 12px;
}

.new-auth .form-field:first-child {
    margin-top: 0;
}

.new-auth .form-field_title {
    font-family: Akrobat;
    font-size: 12px;
    font-weight: 700;
    line-height: 120%; /* 14.4px */
    text-transform: uppercase;
    letter-spacing: 0.48px;

    color: #fff;
    opacity: 0.7;

    display: flex;
    justify-content: space-between;
}

.new-auth .form-field_input {
    margin-top: 4px;
}

.new-auth .prompt {
    opacity: 0.4;
}

/* Button */

.new-auth .form-button {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 10px;

    width: 100%;
    padding: 16px 24px;

    margin-top: 24px;

    font-family: Akrobat;
    font-size: 18px;
    font-style: normal;
    font-weight: 800;
    line-height: 100%; /* 18px */
    text-transform: uppercase;
    color: #151617;

    border: none;
    outline: none;
    border-radius: 300px;

    transition: 0.3s;
}

.new-auth .form-button--color_yellow {
    background: #FFDE2A;
    text-shadow: 0px 0px 20px rgba(255, 255, 255, 0.25);
}
.new-auth .form-button--color_yellow:hover {
    box-shadow: 0px 8px 30px 0px rgba(255, 222, 42, 0.40);
}

.new-auth .form-button--color_grey {
    background: #A6A6A6;
    text-shadow: 0px 0px 20px rgba(255, 255, 255, 0.25);
}

.new-auth .form-button--color_grey:hover {
    background: rgba(255, 255, 255, 0.9);
}

.new-auth .form-button--color_green {
    border-radius: 6px;
    background: rgba(62, 126, 73, 0.20);
    color: #fff;

    transition-duration: 700ms;
}

.new-auth .form-button--color_green:hover 
{
    background: rgba(62, 126, 73, 0.60);
}

.new-auth .form-button img {
    width: 24px;
    height: 24px;
}

/* Checkbox */

.new-auth .form-checkbox {
    position: relative;

    display: flex;
    align-items: center;

    width: 324px;
    height: 32px;
    padding-left: 40px;

    color: rgba(255, 255, 255, 0.5);
    font-family: Akrobat;   
    font-size: 14px;
    font-style: normal;
    font-weight: 700;
    line-height: 116%; /* 16.24px */
    letter-spacing: 0.56px;
    text-transform: uppercase;

    user-select: none;
}

.new-auth .form-checkbox input {
    position: absolute;
    opacity: 0;
    cursor: pointer;
    height: 0;
    width: 0;
}

.new-auth .form-checkbox span {
    position: absolute;
    top: 0;
    left: 0;
    height: 32px;
    width: 32px;
    
    border-radius: 4px;
    border: 2px solid rgba(241, 241, 241, 0.15);
    background: rgba(36, 36, 36, 0.80);
}
.new-auth .form-checkbox--is-missed span {
    border: 2px solid #FB4651;
}

.new-auth .form-checkbox span:after {
    content: "";
    position: absolute;
    display: none;
    
    left: 38%;
    top: 15%;
    width: 8px;
    height: 16px;
    border: solid black;
    border-width: 0 3px 3px 0;
    transform: rotate(45deg);
}

.new-auth .form-checkbox :hover input ~ span {
    background-color: #ccc;
}

.new-auth .form-checkbox  input:checked ~ span {
    border-radius: 4px;
    border: 2px solid #FFDE2B;
    background: #FFDE2B;
    box-shadow: 0px 0px 9px 0px rgba(255, 222, 43, 0.35);
    transition-duration: 500ms;
}

.new-auth .form-checkbox  input:checked ~ span:after {
    display: block;
}

/* Form */

.new-auth .form {
    background: rgba(21, 22, 23, 0.94);
    padding: 44px 42px 36px 42px;

    border-radius: 6px;

    position: relative;
}
.new-auth .form--border_yellow,
.new-auth .form--border_green {
    border-top-left-radius: 0;
    border-top-right-radius: 0;
}

.new-auth .form--border_yellow:before,
.new-auth .form--border_green:before {
    content: "";
    position: absolute;
    top: -6px;
    left: 0;

    width: 100%;
    height: 6px;

    border-top-left-radius: 6px;
    border-top-right-radius: 6px;
}
.new-auth .form--border_yellow:before {
    background: #FFDE2A;
    box-shadow: 0px 8px 30px 0px rgba(255, 222, 42, 0.40);
}
.new-auth .form--border_green:before {
    background: #2FC08B;
    box-shadow: 0px 8px 30px 0px rgba(47, 192, 139, 0.40);
}

/* Input */


.new-auth .form-input.with-icon {
    position: relative;
}

.new-auth .form-input.with-icon:after {
    content: "";

    position: absolute;
    right: 24px;
    top: 50%;
    transform: translateY(-50%);

    width: 22px;
    height: 22px;

    background-size: cover !important;

    transition: 0.3s;
    opacity: 0;
}

.new-auth .form-input.with-icon.b-error:after {
    background: url(./resources/src/client_cef/assets/images/auth/auth/icons/inputs/error.svg);
    
    animation: fadeIn 0.3s forwards;
}
.new-auth .form-input.with-icon.b-success:after {
    background: url(./resources/src/client_cef/assets/images/auth/auth/icons/inputs/success.svg);

    animation: fadeIn 0.3s forwards;
}

.new-auth .form-input.with-icon.with-question:after {
    background: url(./resources/src/client_cef/assets/images/auth/auth/icons/inputs/question.svg);

    animation: fadeIn 0.3s forwards;
}

.new-auth .form-input .question {
    position: absolute;
    right: 24px;
    top: 50%;
    transform: translateY(-50%);

    width: 22px;
    height: 22px;

    background-size: cover !important;

    transition: 0.3s;
    opacity: 1;

    z-index: 1;
}

.new-auth .form-input .question:before {
    content: "";

    position: absolute;
    left: 0;
    top: 0;
    width: inherit;
    height: inherit;

    background: url(./resources/src/client_cef/assets/images/auth/auth/icons/inputs/question-info.svg);
    background-size: cover;

    z-index: 2;

    display: none;
}

.new-auth .form-input .question:hover {
    outline: 8px solid #000;
    border-radius: 300px;

    animation: fadeIn 0.5s forwards;
}

.new-auth .form-input .question_text {
    position: absolute;
    top: 16px;
    left: 50%;
    transform: translateX(-50%);

    width: 172px;
    padding: 8px 6px 10px 6px;
    background: #000;
    border-radius: 8px;

    color: #fff;
    text-align: center;
    text-shadow: 12px 12px 16px rgba(0, 0, 0, 0.40);
    font-family: Akrobat;
    font-size: 14px;
    font-style: normal;
    font-weight: 600;
    line-height: 110%; /* 15.4px */
    letter-spacing: 0.28px;

    z-index: 1;

    display: none;
}

.new-auth .form-input .question:hover:before,
.new-auth .form-input .question:hover .question_text {
    display: block;

    animation: fadeIn 0.3s;
}

.new-auth .form-input input {
    width: 100%;
    height: 60px;
    padding: 18px 24px 20px 24px;

    text-shadow: 12px 12px 16px rgba(0, 0, 0, 0.40);
    font-family: Akrobat;
    font-size: 22px;
    font-style: normal;
    font-weight: 700;
    line-height: 22px; /* 22px */

    color: rgba(255, 255, 255, 0.3);

    border-radius: 6px;
    border: 2px solid rgba(255, 255, 255, 0.05);
    outline: none;
    background: rgba(0, 0, 0, 0.22);

    transition: 0.3s;
}

.new-auth .form-input input::-webkit-outer-spin-button,
.new-auth .form-input input::-webkit-inner-spin-button {
    -webkit-appearance: none;
}

.new-auth .form-input.with-icon input {
    padding-right: 56px;
}

.new-auth .form-input.b-error input {
    border: 2px solid rgba(255, 255, 255, 0.05);
    background: linear-gradient(0deg, rgba(251, 70, 81, 0.10) 0%, rgba(251, 70, 81, 0.10) 100%), rgba(0, 0, 0, 0.22);
}

.new-auth .form-input.b-success input {
    border: 2px solid #3E7E49;
    background: linear-gradient(0deg, rgba(62, 126, 73, 0.20) 0%, rgba(62, 126, 73, 0.20) 100%), rgba(0, 0, 0, 0.22);
}

@keyframes fadeIn {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

