.main-dialog {
    position: absolute;
    width: 100%;
    height: 100vh;
    left: 0;
    top: 0;

    display: flex;
    justify-content: center;
    align-items: center;

    z-index: 9999999;
}

.main-dialog ::-webkit-scrollbar-thumb {
	background: #FFDE2A;
}
.main-dialog ::-webkit-scrollbar {
    width: 4px;
	height: 2px;
	background: rgba(255, 255, 255, 0.25);
}

.main-dialog_box {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;

    width: 408px;
    
    padding: 44px 24px 36px 24px;

    background: rgba(21, 22, 23, 0.94);

    position: relative;
}
.main-dialog_box::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    /* transform: translateY(-100%); */

    width: 100%;
    height: 6px;
    
    background: #FFDE2A;
    box-shadow: 0px 8px 30px 0px rgba(255, 222, 42, 0.40);
}
.main-dialog_box::after {
    content: "";
    position: absolute;
    left: 0;
