.take-car__progress-bar-inner {
    height: 36px;
    background: #2B79FF;
}

.take-car__progress-info {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    height: 28px;
    position: relative;
}

.take-car__progress-item {
    position: absolute;
    left: 0;
    color: rgb(241, 241, 241, 0.2);
    font-size: 28px;
    font-style: normal;
    font-weight: 800;
    line-height: 28px;
    letter-spacing: 0.56px;
    text-transform: uppercase;
    z-index: 0;

}
.take-car__progress-item:nth-of-type(2) {
    left: 50%;
    transform: translateX(-50%);
}
.take-car__progress-item:last-of-type {
    left: auto;
    right: 0;
    transform: translateX(50%);
}
.take-car__progress-item .take-car__progress-item-value,
.take-car__progress-item .inventory-item {
    position: absolute;
    left: 50%;
    top: -78px;
    transform: translate(-50%, -100%);
    z-index: 1;
}
.take-car__progress-item .inventory-item {
    width: 98px;
    height: 98px;
}

.take-car__progress-item .take-car__progress-item-value {
    left: 0;
    transform: translate(0, -100%);
    color: #F1F1F1;
    font-size: 44px;
    font-style: normal;
    font-weight: 800;
    line-height: 44px;
    letter-spacing: 0.88px;
    text-transform: uppercase;
}
.take-car__progress-item > .inventory-item::before {
    content: "";
    position: absolute;
    bottom: -10px;
    left: 50%;
    transform: translateX(-50%);
    width: 2px;
    height: 10px;
    background: rgba(241, 241, 241, 0.60);
    z-index: 0;
}

.take-car__progress-item-fly {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    position: absolute;
    left: 50%;
    top: -204px;
    transform: translate(-50%, -100%);
    z-index: 1;
}
.take-car__progress-item-fly h4 {
    color: #FFDE2A;
    font-size: 16px;
    font-style: normal;
    font-weight: 800;
    line-height: 16px;
    letter-spacing: 1.28px;
    text-transform: uppercase;
}
.take-car__progress-item-fly h5 {
    color: #FFF;
    font-size: 18px;
    font-style: normal;
    font-weight: 800;
    line-height: 18px;
    text-transform: uppercase;
}
.take-car__progress-item-fly p {
    color: #FFDE2A;
    font-size: 12px;
    font-style: normal;
    font-weight: 600;
    line-height: 12px;
    width: fit-content;
    text-wrap: nowrap;
}
