.tablet-wrapper {
    width: 100%;
    height: 100vh;

    display: flex;
    justify-content: center;
    align-items: center;
}

.tablet {
    width: 1176px;
    height: 856px;

    position: relative;

    display: flex;
    justify-content: center;
    align-items: center;

    z-index: 0;
}

.tablet_bg {
    position: absolute;
    left: -2px;
    top: -2px;
    width: 1255px;
    height: 936px;

    z-index: -1000;
}

.tablet-content {
    width: 1090px;
    height: 766px;

    border-radius: 12px;
    overflow: hidden;
}
.tablet-content > div {
    border-radius: 12px;
}

.tablet-esc {
    position: absolute;
    top: 6px;
    right: 6px;

    transition: 0.3s;
}
.tablet-esc:hover {
    transform: scale(1.1, 1.1);
}

/* APPS --> */

/* Desktop App --> */
.tablet-desktop {
    width: 100%;
    height: 100%;

    padding: 64px;

    background: linear-gradient(0deg, rgba(0, 0, 0, 0.20) 0%, rgba(0, 0, 0, 0.20) 100%), url(./resources/src/client_cef/assets/images/tablet/apps/desktop/bg.png) lightgray 50% / cover no-repeat;
}

.tablet-desktop_time {
    text-align: center;

    padding: 64px;
}
.tablet-desktop_time p {
    color: #fff;
    font-family: Akrobat;
    font-size: 100px;
    font-style: normal;
    font-weight: 500;
    line-height: 100px;
    letter-spacing: 4px;
}

.tablet-desktop_apps {
    display: flex;
    justify-content: center;
    gap: 44px;
}

.tablet-desktop_app {
    transition: 0.3s;
}
.tablet-desktop_app:not(.tablet-desktop_app--coming-soon):hover {
    transform: scale(1.1, 1.1);
}
.tablet-desktop_app-logo {
    width: 126px;
    height: 126px;

    border-radius: 32px;
    background: linear-gradient(135deg, #FF9E44 0%, #FBFF44 100%);
    box-shadow: 14px 14px 40px 0px rgba(255, 255, 255, 0.35) inset, -14px -14px 28px 0px rgba(0, 0, 0, 0.25) inset;

    position: relative;
}
.tablet-desktop_app--coming-soon .tablet-desktop_app-logo {
    opacity: 0.67;
    background: linear-gradient(135deg, #111 0%, #404040 100%);
    box-shadow: 14px 14px 40px 0px rgba(0, 0, 0, 0.15);

    display: flex;
    justify-content: center;
    align-items: center;

    color: rgba(241, 241, 241, 0.4);
    text-align: center;
    font-family: Akrobat;
    font-size: 12px;
    font-style: normal;
    font-weight: 900;
    line-height: 12px;
    letter-spacing: 0.24px;
    text-transform: uppercase;
}
.tablet-desktop_app--trucker .tablet-desktop_app-logo {
    background: linear-gradient(229deg, rgba(0, 0, 0, 0.00) 55.42%, rgba(0, 0, 0, 0.50) 76.19%), url(./resources/src/client_cef/assets/images/tablet/apps/desktop/apps/trucker_bg.png) lightgray 50% / cover no-repeat;
    background-size: 200%;
    background-position: 0 0, -46px -93px;
}
.tablet-desktop_app-logo img {
    position: absolute;
    left: 20px;
    bottom: 20px;
}
.tablet-desktop_app-title {
    color: #F1F1F1;
    text-align: center;
    font-family: Akrobat;
    font-size: 12px;
    font-style: normal;
    font-weight: 900;
    line-height: 12px;
    letter-spacing: 0.24px;
    text-transform: uppercase;

    margin-top: 10px;
}

/* <-- Desktop App */

/* Trucker App --> */
.tablet-trucker {
    width: 100%;
    height: 100%;

    display: flex;
}

.tablet-trucker h3 {
    color: #F1F1F1;
    font-family: Akrobat;
    font-size: 24px;
    font-style: normal;
    font-weight: 900;
    line-height: 24px;
}

.tablet-trucker p {
    color: #F1F1F1;
    font-family: Akrobat;
    font-size: 12px;
    font-style: normal;
    font-weight: 700;
    line-height: 12px;
    letter-spacing: 0.48px;
    text-transform: uppercase;
}

.tablet-trucker hr {
    width: 100%;
    outline: 1px solid #f1f1f1;
    border: none;
}

.tablet-trucker_sidebar {
    display: flex;
    flex-direction: column;
    justify-content: space-between;

    width: 200px;
    height: 100%;

    background: #151617;

    padding: 16px;
}

.tablet-trucker_sidebar ul {
    
}

.tablet-trucker_sidebar ul li {
    display: flex;
    justify-content: flex-start;
    align-items: center;
    gap: 12px;

    padding: 18px;

    color: #F1F1F1;
    font-family: Akrobat;
    font-size: 18px;
    font-style: normal;
    font-weight: 700;
    line-height: 18px;
    letter-spacing: 0.36px;
    text-transform: uppercase;

    border-radius: 8px;

    opacity: 0.6;
    transition: 0.3s;
}
.tablet-trucker_sidebar ul li.active,
.tablet-trucker_sidebar ul li:hover {
    opacity: 1;

    background: radial-gradient(487.1% 141.42% at 0% 0%, rgba(241, 241, 241, 0.10) 0%, rgba(97, 97, 97, 0.10) 100%);
}

.tablet-trucker_sidebar ul li img {
    width: 24px;
    height: 24px;
}

.tablet-trucker_sidebar-how-get-truck {

    display: flex;
    flex-direction: column;
    gap: 12px;
    
    padding: 12px;

    border-radius: 8px;
    background: rgba(255, 255, 255, 0.14);

    opacity: 0.6;
    transition: 0.3s;
}
.tablet-trucker_sidebar-how-get-truck:hover {
    opacity: 1;
}
.tablet-trucker_sidebar-how-get-truck img {
    width: 20px;
}
.tablet-trucker_sidebar-how-get-truck p {
    color: #F1F1F1;
    font-size: 18px;
    font-style: normal;
    font-weight: 700;
    line-height: 18px;
    letter-spacing: 0.36px;
    text-transform: uppercase;
}

.tablet-trucker_content {
    width: 100%;
    height: 100%;

    background: #1C2125;
}

.tablet-trucker_content > div {
    width: 100%;
    height: 100%;
}

.tablet-trucker_container {
    padding: 24px;
}

.tablet-trucker .truck-tender {
    width: 270px;

    display: flex;
    flex-direction: column;
    justify-content: space-between;
    gap: 6px;

    border-radius: 8px;
    background: linear-gradient(180deg, #161D1F 0%, #5E7C85 100%);

    padding-bottom: 12px;

    position: relative;
}
.tablet-trucker .truck-tender_image {
    width: 100%;
    min-height: 120px;
    max-height: 120px;

    border-radius: 8px 8px 0 0;

    overflow: hidden;
    position: relative;
}
.tablet-trucker .truck-tender_image img {
    position: absolute;
    left: 0;
    top: 0;

    width: 100%;
    height: 100%;
}
