    display: flex;
    justify-content: center;
    align-items: center;
    height: 100%;
    width: 100%;
    color: #fff;
    flex-direction: column;
    perspective: 1000px;
}
.dark-wrapper.furniturehouse-wrapper.page-1 {
	background: url(./resources/src/client_cef/assets/images/furniture-house/bg-1.png) no-repeat;
	background-size: 100% 100%;
	opacity: 1.0;
	z-index: -10;
}
.dark-wrapper.furniturehouse-wrapper.page-2 {
	background: url(./resources/src/client_cef/assets/images/furniture-house/bg-2.png) no-repeat;
	background-size: 100% 100%;
	opacity: 1.0;
	z-index: -10;
}
.furniturehouse-flex .furniturehouse-types {
    display: flex;
    flex-direction: column;
    align-items: center;
}
.furniturehouse-flex .furniturehouse-types > p {
    font-weight: 800;
    font-size: 80px;
    text-transform: uppercase;
    color: #fff;
    margin-bottom: 75px;
}
.furniturehouse-flex .furniturehouse-types > p > span {
    color: #54cdd2;
    font-weight: 300;
}
.furniturehouse-flex .furniturehouse-types > ul {
    display: grid;
    grid-template-columns: repeat(5, 306px);
    grid-gap: 27px 27px;
}
.furniturehouse-flex .furniturehouse-types > ul > li {
    width: 306px;
    height: 121px;
    border: solid 1px rgba(255,255,255,0.4);
    display: flex;
    align-items: center;
    padding-left: 45px;
    cursor: pointer;
    transition: all 0.23232323s ease-in-out;
    -webkit-transition: all 0.23232323s ease-in-out;
    -moz-transition: all 0.23232323s ease-in-out;
}
.furniturehouse-flex .furniturehouse-types > ul > li > p {
    text-transform: uppercase;
    font-size: 34px;
    font-weight: 800;
}
.furniturehouse-flex .furniturehouse-types > ul > li:hover {
    background-color: rgba(84, 205, 210, 0.2);
    box-shadow: 0px 0px 79px 0px rgba(84, 205, 210, 0.34);
    border: solid 1px rgb(84, 205, 210);
}

.furniturehouse-flex .furniturehouse-range {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 1635px;
    height: 968px;
    position: relative;
}
.furniturehouse-flex .furniturehouse-range .furniturehouse-range-header {
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;
    width: 100%;
    height: 80px;
    min-height: 80px;
    max-height: 80px;
}
.furniturehouse-flex .furniturehouse-range .furniturehouse-range-header > p {
    font-weight: 800;
    font-size: 80px;
    text-transform: uppercase;
    color: #fff;
}
