}
.furniturehouse-flex .furniturehouse-range .furniturehouse-range-none .furniturehouse-range-none-line-2 {
    text-transform: uppercase;
    font-size: 44px;
    margin-bottom: 40px;
}
.furniturehouse-flex .furniturehouse-range .furniturehouse-range-none .furniturehouse-range-none-line-3 {
    text-transform: uppercase;
    font-size: 27px;
    color: rgba(255,255,255,0.4);
}
.furniturehouse-flex .furniturehouse-range > ul {
    display: grid;
    grid-template-columns: repeat(3, 517px);
