.ghettomap-flex {
    height: 100%;
    width: 100%;
    color: #fff;
    display: flex;
    justify-content: flex-end;
    align-items: center;
    flex-direction: column;
}


.ghettomap-flex .hide-map {
	width: 1218px;
	height: 640px;
	overflow: hidden;
	display: flex;
	align-items: center;
	justify-content: center;
	/*
    border-top: solid 50px #fbf7f7;
    border-left: solid 30px #fbf7f7;
    border-right: solid 30px #fbf7f7;
	*/
	position: relative;
}
.ghettomap-flex .map {
	position: relative;
	display:flex;
	/*transform: scale(0.2349, 0.23515);*/
	transform: scale(0.4349, 0.43515);
}

.ghettomap-flex .ghettomap-players-list {
    position: absolute;
    width: 100%;
    height: 100%;
    z-index: 55;
    pointer-events: none;
}
.ghettomap-flex .ghettomap-players-list li {
    background: url(./resources/src/client_cef/assets/images/svg/map-user.svg) no-repeat;
    background-size: 100% 100%;
    width: 10px;
    height: 10px;
    position: absolute;
}
.ghettomap-flex .ghettomap-players-list li.ghettomap-player-self {
    background: url(./resources/src/client_cef/assets/images/svg/map-user-self.svg) no-repeat;
    background-size: 100% 100%;
}

.ghettomap-flex .map .map-figure {
    position: absolute;
}

.ghettomap-flex .map .map-figure.pulse {
	animation: circle 0.5s infinite;
}

/*vagos*/
.ghettomap-flex .map .map-figure.vagos .color-territory{ 
	fill: #FFFF00;
}

/*grove*/
.ghettomap-flex .map .map-figure.grove .color-territory{ 
	fill: #009700;
}

/*aztec*/
.ghettomap-flex .map .map-figure.aztec .color-territory{ 
	fill: #00EAEA;
}

/*ballas*/
.ghettomap-flex .map .map-figure.ballas .color-territory{ 
	fill: #FF00FF;
}

/*bloods*/
.ghettomap-flex .map .map-figure.bloods .color-territory{ 
	fill: #FF0000;
}

.ghettomap-flex .map .map-figure.pulse .color-territory{ 
	fill: #940101;
	
}
.ghettomap-flex .map .map-figure.bloods .color-territory:hover,
.ghettomap-flex .map .map-figure.aztec .color-territory:hover,
.ghettomap-flex .map .map-figure.ballas .color-territory:hover,
.ghettomap-flex .map .map-figure.grove .color-territory:hover,
.ghettomap-flex .map .map-figure.vagos .color-territory:hover{
	fill: #940101;
