@-webkit-keyframes circle {
  0% {
    -webkit-box-shadow: 0 0 0 0 rgba(101, 7, 0, 1.0);
	border-radius:200px;
	display: none;
	opacity: 0.0;
  }
  70% {
      -webkit-box-shadow: 0 0 0 50px rgba(101, 7, 0, 0);
	  border-radius:200px;

  }
  100% {
      -webkit-box-shadow: 0 0 0 0 rgba(101, 7, 0, 0);
	  border-radius:200px;
	  opacity: 1.0;

  }
}
@keyframes circle {
  0% {
    -moz-box-shadow: 0 0 0 0 rgba(101, 7, 0, 1.0);
    box-shadow: 0 0 0 0 rgba(101, 7, 0, 1.0);
	border-radius:200px;
	opacity: 0.0;

  }
  70% {
      -webkit-box-shadow: 0 0 0 50px rgba(101, 7, 0, 0);
	  border-radius:200px;
  }
  100% {
	  transform: scaleX(1.0) scaleY(1.0);
      -webkit-box-shadow: 0 0 0 0 rgba(101, 7, 0, 0);
	  border-radius:200px;
	  opacity: 1.0;
  }
}
