.attacks-history__status-side > div > p > span {
    color: #FF4848;
    font-size: 14px;
    font-style: normal;
    font-weight: 700;
    line-height: 14px;
    letter-spacing: 0.7px;
    text-transform: uppercase;
}
.attacks-history__status-side--defender {
    justify-content: flex-start;
    background: linear-gradient(90deg, rgba(255, 72, 72, 0.50) 0%, rgba(26, 25, 54, 0.00) 70%);

}
.attacks-history__status-side--defender > div {
    align-items: flex-start;
}

.attacks-history__status-side--active {
    background: linear-gradient(90deg, rgba(26, 25, 54, 0.00) 29.81%, #97D44A 100%);
}
.attacks-history__status-side--defender.attacks-history__status-side--active {
    background: linear-gradient(90deg, #97D44A 0%, rgba(26, 25, 54, 0.00) 70.19%);
}
.attacks-history__status-side--active > div > p > span {
